use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut current = Vec::new();
    let mut current_index = 0;

    for item in input.as_array() {
        if let Some(sub_item) = item.as_array() {
            for sub_item in sub_item {
                current.push(sub_item);
            }
        } else {
            current.push(item);
        }
    }

    while current_index < current.len() {
        result.push(current[current_index]);
        current_index += 1;
    }

    serde_json::Value::from(result)
}
